static void queue_pending_template_spec_in_namespace_bound(TokenString *str,
                                                      int dependency_tok,
                                                      int namespace_tok,
                                                      unsigned replay_bound,
                                                      int replay_class_tok)
{
  if (cpp_trace_incomplete())
    fprintf(stderr, "[q] dep=%s class=%s bound=%u\n",
            dependency_tok ? get_tok_str(dependency_tok, NULL) : "",
            replay_class_tok ? get_tok_str(replay_class_tok, NULL) : "",
            replay_bound);
  if (nb_pending_template_specs >= al_pending_template_specs)
  {
    al_pending_template_specs = al_pending_template_specs
                                ? al_pending_template_specs * 2 : 16;
    pending_template_specs = cprime_realloc(
      pending_template_specs,
      al_pending_template_specs * sizeof(*pending_template_specs));
    pending_template_spec_dependency_toks = cprime_realloc(
      pending_template_spec_dependency_toks,
      al_pending_template_specs
        * sizeof(*pending_template_spec_dependency_toks));
    pending_template_spec_namespace_toks = cprime_realloc(
      pending_template_spec_namespace_toks,
      al_pending_template_specs * sizeof(*pending_template_spec_namespace_toks));
    pending_template_spec_next = cprime_realloc(pending_template_spec_next,
      al_pending_template_specs * sizeof(*pending_template_spec_next));
    pending_template_spec_bounds = cprime_realloc(pending_template_spec_bounds,
      al_pending_template_specs * sizeof(*pending_template_spec_bounds));
    pending_template_spec_class_toks = cprime_realloc(
      pending_template_spec_class_toks,
      al_pending_template_specs * sizeof(*pending_template_spec_class_toks));
    pending_template_spec_default_arg_owner_toks = cprime_realloc(
      pending_template_spec_default_arg_owner_toks,
      al_pending_template_specs * sizeof(*pending_template_spec_default_arg_owner_toks));
    pending_template_spec_semantic_only = cprime_realloc(
      pending_template_spec_semantic_only,
      al_pending_template_specs * sizeof(*pending_template_spec_semantic_only));
  }
  pending_template_specs[nb_pending_template_specs] = str;
  pending_template_spec_dependency_toks[nb_pending_template_specs] =
    dependency_tok;
  pending_template_spec_namespace_toks[nb_pending_template_specs] = namespace_tok;
  pending_template_spec_next[nb_pending_template_specs] = nb_pending_template_specs + 1;
  pending_template_spec_bounds[nb_pending_template_specs] = replay_bound;
  pending_template_spec_class_toks[nb_pending_template_specs] = replay_class_tok;
  pending_template_spec_default_arg_owner_toks[nb_pending_template_specs] = 0;
  pending_template_spec_semantic_only[nb_pending_template_specs] = cpp_unused_body_validation != 0;
  ++nb_pending_template_specs;
}

static void queue_pending_template_spec_in_namespace(TokenString *str,
                                                      int dependency_tok,
                                                      int namespace_tok)
{
  queue_pending_template_spec_in_namespace_bound(str, dependency_tok,
                                                 namespace_tok, 0, 0);
}

static void queue_pending_template_member_proto(TokenString *str, int class_tok)
{
  queue_pending_template_spec_in_namespace(str, class_tok,
                                           symbol_namespace_scope_tok(class_tok));
  pending_template_spec_default_arg_owner_toks[nb_pending_template_specs - 1] = class_tok;
}

/* Keep stable queue indices while skipping consumed entries. A blocked item
   near the front must not make every later drain rescan thousands of holes.
   A link to the current end remains valid when another item is appended. */
static int next_pending_template_spec(int index)
{
  int first = index;
  while (index < nb_pending_template_specs && !pending_template_specs[index])
    index = pending_template_spec_next[index];
  while (first < index) {
    int next = pending_template_spec_next[first];
    pending_template_spec_next[first] = index;
    first = next;
  }
  return index;
}

static void queue_pending_template_spec(TokenString *str, int dependency_tok)
{
  queue_pending_template_spec_in_namespace(str, dependency_tok,
                                           current_namespace_scope_tok());
}

